fn solve(x: i32) -> i32 {
    let mut score = 0;

    // Determine the digit and the length of the boring apartment number
    let digit = x.to_string().chars().next().unwrap().to_digit(10).unwrap() as i32;
    let length = x.to_string().len() as i32;

    // Calculate the score for all boring numbers with digits 1 to (digit - 1)
    for d in 1..digit {
        // For each digit d, we have 1, 2, 3, 4 presses for d, dd, ddd, dddd
        score += 1 + 2 + 3 + 4; // This is 10 presses for each digit
    }

    // Now calculate the score for the current digit up to the current length
    // For the current digit, we count from d, dd, ..., up to the current length
    score += (1..=length).sum::<i32>(); // This sums 1 + 2 + ... + length

    score
}